/// One in-order pass (`max_iter(1)`, no shuffling) and the per-row
/// `partial_fit` stream both equal sklearn's `partial_fit` on the same rows.
#[test]
fn single_online_pass_matches_sklearn_partial_fit() {
    let n = N_PA_STREAM;
    let p = P_PA_STREAM;
    let x = Mat::from_fn(n, p, |i, j| X_PA_STREAM_FLAT[i * p + j]);
    let y = Col::from_fn(n, |i| Y_PA_STREAM[i]);
    let cases = [
        (
            PaLoss::EpsilonInsensitive,
            EXPECTED_INTERCEPT_STREAM_PA1,
            EXPECTED_COEFS_STREAM_PA1,
        ),
        (
            PaLoss::SquaredEpsilonInsensitive,
            EXPECTED_INTERCEPT_STREAM_PA2,
            EXPECTED_COEFS_STREAM_PA2,
        ),
    ];
    for (loss, intercept, coefs) in cases {
        let pa = PassiveAggressiveRegressor::builder()
            .c(0.5)
            .epsilon(0.05)
            .max_iter(1)
            .shuffle(false)
            .loss(loss)
            .build();
        let fitted = pa.fit(&x, &y).unwrap();
        assert!((fitted.result().intercept.unwrap() - intercept).abs() < 1e-10);
        let mut state = anofox_regression::solvers::PaState::new(p);
        for i in 0..n {
            let row: Vec<f64> = (0..p).map(|j| x[(i, j)]).collect();
            pa.partial_fit(&mut state, &row, y[i]).unwrap();
        }
        assert!((state.intercept - intercept).abs() < 1e-10);
        for j in 0..p {
            assert!(
                (fitted.result().coefficients[j] - coefs[j]).abs() < 1e-10,
                "{loss:?} coef[{j}] {} vs sklearn {}",
                fitted.result().coefficients[j],
                coefs[j]
            );
            assert!((state.weights[j] - coefs[j]).abs() < 1e-10);
        }
    }
}
